import{_ as o,o as r,c as t,a0 as a}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"CoinEx 注意事项","description":"","frontmatter":{},"headers":[],"relativePath":"cursor/coinex.md","filePath":"cursor/coinex.md","lastUpdated":1791573371000}'),i={name:"cursor/coinex.md"};function s(n,e,l,c,d,u){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="coinex-注意事项" tabindex="-1">CoinEx 注意事项 <a class="header-anchor" href="#coinex-注意事项" aria-label="Permalink to &quot;CoinEx 注意事项&quot;">​</a></h1><h2 id="信任工作区" tabindex="-1">信任工作区 <a class="header-anchor" href="#信任工作区" aria-label="Permalink to &quot;信任工作区&quot;">​</a></h2><h3 id="强制开启-信任工作区-询问" tabindex="-1">强制开启“信任工作区”询问 <a class="header-anchor" href="#强制开启-信任工作区-询问" aria-label="Permalink to &quot;强制开启“信任工作区”询问&quot;">​</a></h3><p>确保 Cursor 不会自动信任任何新打开的文件夹。</p><ul><li><strong>设置路径：</strong> <code>Settings</code> -&gt; <code>Features</code> -&gt; 搜索 <strong>&quot;Trust&quot;</strong> 或进入 <code>Security</code> 相关选项</li><li><strong>操作：</strong> 确保 <strong><code>Security &gt; Workspace &gt; Trust: Enabled</code></strong> 是勾选状态</li><li><strong>效果：</strong> 每次打开新项目时，Cursor 必须弹窗询问“是否信任此作者”</li></ul><h3 id="严格区分-受限模式-与-信任模式" tabindex="-1">严格区分“受限模式”与“信任模式” <a class="header-anchor" href="#严格区分-受限模式-与-信任模式" aria-label="Permalink to &quot;严格区分“受限模式”与“信任模式”&quot;">​</a></h3><p>当你从 GitHub 下载或者克隆一个不完全熟悉的仓库时，<strong>永远先选择“不信任（Restricted Mode）”</strong></p><ul><li><strong>在受限模式下：</strong> AI 仍然可以阅读代码并回答问题，但它<strong>无法</strong>自动执行终端命令、无法运行项目中的任务（Tasks），也无法调用某些可能导致系统变更的插件</li><li><strong>风险点：</strong> 文章指出的漏洞通常是在你点击“信任”后，AI 会自动读取项目中的恶意配置文件（如特定的提示词注入），并在你没注意时利用你的信任权限执行 RCE（远程代码执行）</li></ul><h3 id="清理已有的-信任列表" tabindex="-1">清理已有的“信任列表” <a class="header-anchor" href="#清理已有的-信任列表" aria-label="Permalink to &quot;清理已有的“信任列表”&quot;">​</a></h3><p>你可能在无意中信任了许多不再需要的仓库。</p><p><strong>操作：</strong></p><ol><li>按下 <code>Ctrl+Shift+P</code> (Win/Linux) 或 <code>Cmd+Shift+P</code> (Mac)。</li><li>输入并选择 <strong>“Workspaces: Manage Workspace Trust”</strong>。</li><li>查看 <strong>“Trusted Folders &amp; Workspaces”</strong> 列表。</li><li><strong>移除</strong>所有不常用、或来自外部下载的第三方项目路径。</li></ol><h2 id="review-分支" tabindex="-1">review 分支 <a class="header-anchor" href="#review-分支" aria-label="Permalink to &quot;review 分支&quot;">​</a></h2><ul><li>切换功能分支（feature/1113-token-info）</li><li>在 Diff Against 那里选择要比较的分支，例如 release/0.4</li><li>最后点击 Find Issues</li></ul>',14)])])}const p=o(i,[["render",s]]);export{h as __pageData,p as default};
